DO $$ DECLARE b text; BEGIN SELECT pg_get_functiondef(p.oid) INTO STRICT b FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='rpc_regulatory_dossier_new_version'; b:=replace(b,'where microorganism_id = v.microorganism_id','where ((v.product_id IS NULL AND product_id IS NULL AND microorganism_id=v.microorganism_id) OR (v.product_id IS NOT NULL AND product_id=v.product_id))'); EXECUTE b; END $$;